data.code:
terraform {
  required_version = ">= 1.7.0"

  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 4.0"
    }
  }

  backend "azurerm" {
    resource_group_name  = "rg-tfstate"
    storage_account_name = "sttfstatequotient"
    container_name       = "tfstate"
    key                  = "prod/quotient.tfstate"   # one key per environment
    use_azuread_auth     = true                       # no storage account key
  }
}
